vocab => [
['Acronym', 'n. 缩写', 'CDE, GLM, MDM — every one is a door; collect them, do not dodge them.'],
['Legacy', 'adj. 历史遗留的', 'Older than the current team and load-bearing anyway. "Do not ask" usually follows.'],
['Topology', 'n. 拓扑', 'Which system feeds which — the map you confirm before diving deeper.'],
['Master data management (MDM)', 'abbr. 主数据管理', 'The referee that rejects records inconsistent with golden data.'],
['DQ dashboard', 'n. 数据质量仪表盘', 'Where rejected or suspect records surface for humans.'],
['On-call', 'n. 值班', 'The person with the pager this week; paged via PD (PagerDuty).'],
['BCP', 'abbr. 业务连续性计划', 'The documented fallback when systems fail — "on paper" doing heavy lifting.'],
['Chaser', 'n. 跟进提醒', 'A polite repeated request; the verb is "to chase".'],
['The business', 'n. 业务方', 'Whoever asked for the work — seniority depends on the room.'],
['Spacer / padding field', 'n. 填充字段', 'A fixed-width filler in extracts — and, in another team, a calendar gap.'],
],
grammar => [
['Defining relative clauses build the map', q{<em>"MDM sits in between and can reject the record, in which case it lands on the DQ dashboard."</em> — the <strong>in which case</strong> clause chains system behaviour into one sentence: [A does X], in which case [B happens]. Systems talk in exactly this grammar — learn to hear the chain: feeds, sits, rejects, lands, pages. Each verb is a pipe.}, q{"MDM sits in between and can reject the record, in which case it lands on the DQ dashboard."——<strong>in which case</strong> 从句把系统行为串进一句话：[A 做 X]，in which case [B 发生]。系统语言正是这种语法——学会听链条：feeds、sits、rejects、lands、pages。每个动词都是一根管道。}],
['Quotation marks as a decoder signal', q{<em>When someone says "that needs a spacer" — is that a calendar thing or a data thing?</em> Spoken English cannot use quotation marks, so we do it with voice and with <strong>when someone says X</strong> framing. The frame tells the room you are quoting a tribe\'s idiom, not describing the world — which is exactly the register for asking what a word means without seeming lost.}, q{口头英语没有引号，用语音和 <strong>when someone says X</strong> 框架来代替。这个框架告诉全场：你在引用某个部落的习语，而不是描述世界——这正是"问一个词什么意思"而不显得迷茫的语域。}],
],
tips => [
q{<strong>Two columns, always.</strong> Heard / think-it-means. Fill the right column after the meeting, verify with a human before the day ends.},
q{<strong>Read the topology back before asking questions.</strong> "Did I get the map right?" earns corrections for free and shows you process out loud.},
q{<strong>Acronyms are legacy and load-bearing.</strong> Do not ask why GLM is called GLM — ask what it does. The history is unknowable; the function is not.},
q{<strong>Namespaces matter.</strong> The same acronym in two teams is two words. When in doubt, ask which team\'s version it is.},
q{<strong>Decode the sarcasm too.</strong> "There is a fallback process on paper" is a status report in disguise — the paper eyebrow is part of the meaning.},
],
practice => [
{ t => 'Start your two-column page', p => 'From your team\'s last meeting (or this dialogue), list ten terms: left column as heard, right column as you understand them. Mark two you are least sure of.', a => q{The two marked terms are tomorrow\'s coffee questions — specific, small, and flattering to answer ("you want to know what WE mean by chaser?"). Uncertainty, made precise, becomes a networking tool.} },
{ t => 'Topology speak', p => 'Describe this flow in three chained sentences using the verb vocabulary: CDE → MDM → GLM → DQ dashboard → PD.', a => q{Model: "CDE pushes nightly to MDM. MDM validates and either forwards to GLM or rejects. Rejects land on the DQ dashboard, which pages the on-call via PD." Verbs as pipes: pushes, validates, forwards, rejects, land, page.} },
